internal object DuaAmDraft2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_allahumma_bika_asbahna" to DuaText("አላሁማ ቢካ አስባህና።", "አሏህ ሆይ በአንተ ማለዳ እንገባለን በአንተም መሸ እንገባለን። በአንተ እንኖራለን በአንተም እንሞታለን ትንሣኤም ለአንተ ብቻ ነው።", "ጠዋት ላይ.", "ነብዩ ﷺ ዛሬ ጠዋት እና ማታ እንዲናገሩ ለሶሓቦች አስተምረዋል።"),
        "dua_allahumma_bika_amsayna" to DuaText("አላሁማ ቢካ አምሳይና።", "አላህ ሆይ በአንተ ማምሻችንን እንገባለን በአንተም ማለዳ እንገባለን። በአንተ እንኖራለን በአንተም እንሞታለን መመለሻም ወደ አንተ ብቻ ነው።", "ምሽት ላይ.", "ነብዩ ﷺ ዛሬ ጠዋት እና ማታ እንዲናገሩ ለሶሓቦች አስተምረዋል።"),
        "dua_afiyah_morning" to DuaText("አፊያህን በመጠየቅ", "አላህ ሆይ በዱንያም በአኺራም ምህረትንና ደህንነትን እለምንሃለሁ።", "ነብዩ ﷺ ይህን ዱዓ ጥዋትም ማታም አልተዉም።", "ማንም ከደህንነት የተሻለ ነገር አልተሰጠም።"),
        "dua_afini_fi_badani" to DuaText("የሰውነት ፣ የመስማት እና የማየት ጤና", "አላህ ሆይ ለሰውነቴ ጤናን ስጥ። አሏህ ሆይ የመስማትን ጤና ስጥልኝ። አሏህ ሆይ ለአይኔ ፀጋን ስጠኝ። ከአንተ በቀር አምላክ የለም።", "ጠዋት እና ማታ ሶስት ጊዜ.", "ዱዓ ለጤና እና ለስሜቶች ጥበቃ።"),
        "dua_ya_hayyu_aslih" to DuaText("ሁሉንም ጉዳዮቼን አስተካክል።", "ሁል ጊዜ የምትኖር ጌታ ሆይ በምህረትህ እርዳታን እሻለሁ ጉዳዮቼን ሁሉ አስተካክል ለዓይን ጥቅሻ እንኳን ለራሴ አትተወኝ።", "ነቢዩ ﷺ ፋጢማ (RA) ጠዋት እና ማታ እንድትናገር መክሯታል።", "በሁሉም ጉዳይ ላይ የአላህን እርዳታ መጠየቅ።"),
        "dua_subhanallah_adada_khalqihi" to DuaText("ተስቢህ የጁወይሪያ (RA)", "ለአላህ ክብር ይገባው ምስጋናም ሁሉ ለእርሱ የተገባ ነው - የፈጣሪውን ያህል፣ የወደደውን ያህል፣ የዐርሹ ክብደትና የቃሉ ቀለም እኩል ነው።", "ጠዋት ሶስት ጊዜ - ከዚክር ሰአታት የበለጠ ክብደት ያለው።", "እነዚህን አራት ሀረጎች ሶስት ጊዜ መናገር ከንጋት ጀምሮ እስከ ጥዋት አጋማሽ ድረስ ያለውን ዚክር ይበልጣል።"),
        "dua_salawat" to DuaText("ዱሩድ-ኢ-ኢብራሂሚ", "አላህ ሆይ በሙሀመድ ﷺ እና በሙሀመድ ቤተሰብ ላይ ኢብራሂም (AS) እና የኢብራሂም ቤተሰቦች ላይ ጸሎት እንዳላክክ ሁሉ አንተ የተመሰገነ ነህ፣ የተከበርክ ነህ። አሏህ ሆይ ሙሐመድን ﷺ እና የመሐመድን ቤተሰቦች ኢብራሂምን (AS) እንደባረክህ እና የኢብራሂም ቤተሰቦችን አብርክ። አንተ የተመሰገነ ነህ፣ የተከበርክ ነህ።", "ሰለዋት በነብዩ ላይ ﷺ በሶላት እና በማንኛውም ጊዜ።", "አንድ ጊዜ ሰለዋት ያወረደ አላህ በሱ ላይ አስር ​​እዝነት ያወርድበታል (ሙስሊም 408)።"),
        "dua_wudu_after" to DuaText("ከውዱ በኋላ", "ሊመለክ የሚገባው አላህ ብቻ እንደሆነ፣ ብቻውን፣ አጋር የሌለው፣ ሙሐመድ ﷺ ባሪያውና መልእክተኛው መሆናቸውን እመሰክራለሁ። አላህ ሆይ ከሚጸጸቱት እና ከሚጠሩት መካከል አድርገኝ።", "ዉዱእ ካጠናቀቁ በኋላ።", "በፈለገው እንዲገባ ስምንቱ የጀነት በሮች ተከፍተውለታል።"),
        "dua_wudu_before" to DuaText("ከዉዱእ በፊት", "በአላህ ስም።", "ዉዱእ ሲጀመር።", "በላዩ ላይ የአላህን ስም ለማይጠራ ሰው ምንም (የተሟላ) ዉዱእ የለም።"),
        "dua_istiftah" to DuaText("የመክፈቻ ልመና (ሳና)", "አላህ ሆይ ክብር ላንተ ይሁን ምስጋናም ላንተ ይሁን። ስምህ የተመሰገነ ነው ግርማ ሞገስህ ከፍ ያለ ነው ከአንተ በቀር አምላክ የለም።", "ሶላት ሲጀመር ተክቢር ከተከፈተ በኋላ።", "የሱና መክፈቻ ዱዓ።"),
        "dua_ruku" to DuaText("በሩኩ", "ክብር ለታላቁ ጌታዬ ይሁን።", "በሩኩ ውስጥ ቢያንስ ሶስት ጊዜ.", "የሩኩ ሱና ተስቢህ።"),
        "dua_sujood" to DuaText("በሱጁድ", "ክብር ለልዑል ጌታዬ ይሁን።", "በሱጁድ ቢያንስ ሶስት ጊዜ።", "ባሪያው ሱጁድ ላይ እያለ ለጌታው በጣም ቅርብ ነው (ሙስሊም 482)።"),
        "dua_rising_ruku" to DuaText("ከሩኩ መነሳት", "አላህ ያመሰገነውን ሰው ይሰማል። ጌታችን ሆይ ምስጋና ላንተ ይገባው።", "ከሩኩ ተነስተው ቀጥ ብለው ሲቆሙ።", "ማንም 'ራብና ወ ላካል-ሃምድ' ከመላእክቱ ጋር የሚገጣጠም ያለፈው ኃጢአቱ ይሰረይለታል።"),
        "dua_between_sajdas" to DuaText("በሁለቱ ሳጅዳዎች መካከል", "ጌታዬ ሆይ ይቅር በለኝ ጌታዬ ሆይ ይቅር በለኝ", "በሁለቱ ሱጁዶች መካከል ተቀምጦ ሳለ።", "በስግደት መካከል ያለው የመቀመጫ የሱና ዱዓ።"),
        "dua_before_salam_four" to DuaText("ከአራት ነገሮች መሸሸጊያ (ከሰላም በፊት)", "አላህ ሆይ፣ ከጀሀነም ቅጣት፣ ከመቃብር ቅጣት፣ ከህይወትና ከሞት ፈተና፣ ከውሸት መሲህ (ደጃል) ፈተና ክፋት በአንተ እጠበቃለሁ።", "ከመጨረሻው ተሻሁድ እና ሰለዋት በኋላ፣ ከሰላም በፊት።", "ነብዩ ﷺ ከነዚህ አራት ነገሮች መጠጊያ መፈለግን አዘዙ።"),
        "dua_qunoot_witr" to DuaText("Qunoot በዊትር", "አሏህ ሆይ አንተ ከመራሃቸው ሰዎች መካከል ምራኝ፣ ምህረትን ከሰጠሃቸው ሰዎች መካከል ምህረትን ስጠኝ፣ ወደ እንክብካቤህ ከወሰድካቸው ሰዎች ውስጥ ወደ አንተ እንክብካቤ አድርገኝ፣ በሰጠኸው ነገር ባርከኝ፣ ከወሰንክበት መጥፎ ነገር ጠብቀኝ። በአንተ ላይ ወስነሃል፤ አንድም አይፈርድብህም፤ ያደረግከውም ሰው ፈጽሞ አይዋረድም። የተባረክህ እና የተከበርክ ነህ ጌታችን።", "በዊትር ሶላት - ነቢዩ ﷺ ለሀሰን ኢብን አሊ (RA) አስተምረውታል።", "የዊትር ሱና ኩኑት። (ከሐነፊዎች መካከል “አላሙማ ኢንና ናስታኢኑካ” በሰፊው ይታወቃል።)"),
        "dua_qunoot_hanafi" to DuaText("ኩኑት (አላሁማ ኢና ናስታኢኑካ)", "አሏህ ሆይ እርዳታህን እና ምህረትህን እንለምንሃለን ባንተ አምነናል ባንተም ተመኪተናል፡እናመሰግንሃለን፡እናመሰግንሃለን ከሓዲዎችም አይደለንም፤የታዘዝክን ሁሉ እንተዋለን። አሏህ ሆይ አንተን ብቻ እናመልካለን ወደ አንተ እንጸልያለን እንሰግዳለን ወደ አንተ እንቸኩላለን እንታገላለን ምህረትህን ተስፋ እናደርጋለን ቅጣህንም እንፈራለን:: ቅጣታችሁ በከሓዲዎችን በእርግጥ ይደርሳል።", "በዊትር - የሃናፊዎች ልምምድ.", "ከኡመር (RA) በኩኑት ተዘገበ።"),
        "dua_sleep_aslamtu" to DuaText("ከመተኛቱ በፊት የመጨረሻዎቹ ቃላት", "አላህ ሆይ ራሴን ለአንተ አስገዛለሁ፣ ጉዳዬን ላንተ አደራ እሰጣለሁ፣ ጀርባዬንም ለአንተ ጥበቃ አደርጋለሁ፣ ባንተ ተስፋ እና አንተን በመፍራት። ከአንተ በቀር መጠጊያና ማምለጫ የለም። እኔ ባወረድከው መጽሐፍህና በላክከው ነቢይ አምናለሁ።", "ከውዱ በኋላ በቀኝ በኩል መተኛት - ከመተኛቱ በፊት በጣም የመጨረሻዎቹ ቃላት።", "በዚያች ሌሊት ከሞተ በፊታው (በእስልምና) ላይ ይሞታል።"),
        "dua_waking_night" to DuaText("በምሽት መነሳት", "ሊመለክ የሚገባው አላህ ብቻ ነው፣ እርሱ ብቻውን ነው፣ አጋር የለውም። ንግሥናው የርሱ ብቻ ነው፤ ምስጋናም የርሱ ብቻ ነው። እርሱም በነገሩ ሁሉ ላይ ቻይ ነው። ምስጋና ሁሉ ለአላህ የተገባ ነው፡ ክብር ለአላህ ይገባው፡ ሊመለክ የሚገባው አላህ ብቻ ነው፡ አላህ ታላቁ ነው፡ ከአላህ ጋር ካልሆነ በስተቀር ምንም ሃይልም ሆነ ሃይል የለም። አላህ ሆይ ይቅር በለኝ።", "በሌሊት ሲነቃ.", "ዱዓውም ተሰምቷል፡ ዉዱእ አድርጎ ከሰገደ በኋላ ጸሎቱ ተቀባይነት ይኖረዋል።"),
        "dua_hamm_ibn_masud" to DuaText("የሀዘን ዱዓ (ኢብኑ መስዑድ)", "አላህ ሆይ እኔ ባሪያህ ነኝ የባሪያህ ልጅ የባሪያህ ልጅ ነኝ። አንገቴ በእጅህ ነው፥ ትእዛዝህ በእኔ ላይ ተፈጽሟል፥ በእኔም ላይ ያደረግከው ትእዛዝ ትክክል ነው። I ask You by every name that is Yours, with which You named Yourself, or revealed in Your Book, or taught to any of Your creation, or kept with Yourself in the knowledge of the unseen — that You make the Quran the spring of my heart, the light of my chest, the removal of my sorrow and the departure of my worry.", "በሀዘን እና በጭንቀት - አላህ ሀዘኑን በደስታ ይተካዋል.", "አላህ ጭንቀትንና ሀዘኑን አስወግዶ በምትኩ ደስታን ሰጠው።"),
        "dua_difficulty_sahl" to DuaText("አንድ ነገር አስቸጋሪ በሚሆንበት ጊዜ", "አላህ ሆይ ካቀለኸው በስተቀር ቀላል ነገር የለም አንተም ከፈለግክ አስቸጋሪውን ቀላል ታደርጋለህ።", "አንድ ነገር አስቸጋሪ ሆኖ ሲሰማ.", "በፈተናዎች ውስጥ ቀላልነት እና አስቸጋሪ ስራዎች."),
        "dua_musibah" to DuaText("በአደጋ ላይ (ኢስቲርጃ)", "እኛ የአላህ ነን ወደርሱም ተመላሾች ነን። አላህ ሆይ!", "በማንኛውም ኪሳራ ወይም ጥፋት ላይ።", "አላህ በእርግጥ የተሻለ ነገርን ይሰጣል - ኡሙ ሰላማ (RA) ለነቢዩ ﷺ ተሰጥቷታል።"),
        "dua_debt" to DuaText("ከዕዳ ለመገላገል", "አላህ ሆይ እርም ባደረግከው ነገር ላይ የፈቀድከኝ ይብቃኝ በችሮታህም ካንተ ውጪ ካሉት ሁሉ ነፃ አድርገኝ።", "ዕዳ ለመክፈል - በአሊ (RA) ተምሯል.", "እዳው እንደ ተራራ ቢሆንም አላህ ያስተካክለዋል።"),
        "dua_anger" to DuaText("ሲናደድ", "ከተረገመው ሸይጣን በአላህ እጠበቃለሁ።", "ሲናደድ።", "ነቢዩ ﷺ እንዲህ ብለዋል፡- ይህን ከተናገረ ንዴቱ ይጠፋል።"),
        "dua_waswasa" to DuaText("በእምነት ዋስዋሳ ላይ", "በአላህና በመልክተኞቹ አምናለሁ።", "ስለ እምነት ሰይጣናዊ ሹክሹክታ ሲመጣ።", "ሹክሹክታ ሲመጣ ይህን ተናገር እና እዚያ ቆም (በአላህም ተጠበቅ)።"),
        "dua_travel_full" to DuaText("የተሟላ የጉዞ ልመና", "አሏህ ሆይ በዚህ ጉዞህ ላይ ለጽድቅ እና ለቅህመት እንዲሁም አንተን የሚያስደስት ስራ እንጠይቅሃለን። አላህ ሆይ ይህን ጉዞ አቅልልን ርቀቱንም አሳጥረን። አሏህ ሆይ አንተ የጉዞ አጋር እና የቤተሰብ ጠባቂ ነህ።", "ለጉዞ ሲነሳ ከሱብሃነላዲ ሰክሃራ በኋላ።", "የተሟላ የሱና የጉዞ ዱዓ።"),
        "dua_return_travel" to DuaText("ከጉዞ መመለስ", "እየተመለስን ንሰሀ እየገባን ጌታችንን እያመለክን እያመሰገንን ነው።", "ከጉዞ ሲመለሱ።", "ነቢዩ ﷺ ከጉዞ ሲመለሱ እንዲህ ብለው ነበር።"),
        "dua_farewell_traveller" to DuaText("ለተጓዥ የመሰናበቻ ጨረታ", "ለአላህ ሀይማኖታችሁን፣ አደራችሁን እና የስራችሁን ፍፃሜ አደራ እላለሁ።", "መንገደኛ ስንብት ሲጫረት።", "ለአላህ የተሰጠ አደራ አይጠፋም።"),
        "dua_entering_town" to DuaText("በአንድ ቦታ ላይ ማቆም", "ፍፁም በሆነው የአላህ ቃል እጠበቃለሁ ከፈጠራቸው ሁሉ ክፋት።", "በአንድ ቦታ ላይ ሲያቆሙ ወይም አዲስ ከተማ ሲደርሱ.", "ከዚያ እስካልወጣ ድረስ ምንም አይጎዳውም።"),
        "dua_boarding_ship" to DuaText("መርከብ / ተሽከርካሪ መሳፈር", "በአላህ ስም መርከቧ እና መቆሚያዋ ነው። ጌታዬ መሓሪ አዛኝ ነውና።", "በመርከብ ወይም በተሽከርካሪ ሲሳፈሩ - የነቢዩ ኑህ ቃል (AS)።", "የቁርዓን አንቀጽ - የኑህ (AS) ታቦት ዱዓ።"),
        "dua_istighfar_hayyul_qayyum" to DuaText("ኢስቲግፋር ከሀዩል-ቀይዩም ጋር", "ከአላህ ምህረትን እለምናለሁ ከእርሱ ሌላ አምላክ የሌለ ህያው ሲሳይ ወደእርሱም እጸጸታለሁ።", "ለንስሐ.", "ከጦር ሜዳ ቢሸሽም ኃጢአቱ ተሰርዮለታል።"),
        "dua_rabbighfir_warham" to DuaText("Rabbighfir Warham", "ጌታዬ ሆይ ይቅር በለን እዘንም አንተ ከምሕረት ሁሉ በላጭ ነህና።", "የቁርዓን ዱዓ - ለምህረት እና ለምህረት።", "የሱረቱ አል-ሙእሚኑን የመጨረሻ አንቀጽ።"),
        "dua_majlis_kaffarah" to DuaText("ካፋራት አል መጅሊስ", "አላህ ሆይ ክብር ላንተ ይሁን ምስጋናም ላንተ ይሁን። ከአንተ በቀር ሌላ አምላክ እንደሌለ እመሰክራለሁ። ይቅርታህን እጠይቃለሁ እና ወደ አንተ በንስሐ እመለሳለሁ.", "ከስብሰባ ሲነሱ።", "በተሰብሳቢው ላይ ለተነገረው ስህተት ሁሉ ማስተሰረያ ይሆናል።"),
        "dua_jami_forgiveness" to DuaText("ሁሉን አቀፍ ይቅርታ", "አሏህ ሆይ ስህተቶቼን፣ ድንቁርናዬን፣ በጉዳዮቼ ላይ ያለኝን ትርፍ፣ ከእኔ በላይ የምታውቀውን ሁሉ ይቅር በለኝ።", "አጠቃላይ የነብዩ ዱአ ﷺ።", "ነብዩ ﷺ ይህንን ዱዓ ያደርጉ ነበር።"),
        "dua_parents_nuh" to DuaText("የኑህ (AS) ዱዓ ለወላጆች", "ጌታዬ ሆይ ለኔ፣ ለወላጆቼ፣ ወደ ቤቴ አማኝ ሆኖ የገባን ሰው፣ ምእመናንም ወንዶችና ምእመናን ሁሉ ይቅር በላቸው።", "ለወላጆች እና ለምእመናን.", "የነቢዩ ኑህ (AS) ዱአ።"),
        "dua_shukr_parents" to DuaText("ለወላጆች እና ለጻድቅ ዘሮች ምስጋና", "ጌታዬ ሆይ በእኔና በወላጆቼ ላይ የለገስከውን ችሮታ እንዳመሰግን አንተን ደስ የሚያሰኝ ስራ እንድሰራ፣ ዘሮቼንም ፃድቅ እንዳደርግ አስረገኝ። በጸጸት ወደ አንተ እመለሳለሁ፤ እኔም ከተገዢዎቹ ነኝ።", "አርባ አመት የመድረስ የቁርዓን ዱአ።", "ምስጋና፣ መልካም ስራዎች እና የአንድ ልጆች ጽድቅ - ሁሉም በአንድ ዱዓ።"),
        "dua_intimacy" to DuaText("ከጋብቻ ግንኙነት በፊት", "በአላህ ስም። አላህ ሆይ ሸይጣንን ከኛ አርቀን ሸይጣንን ከሰጠኸን (ልጆች) አርቀን።", "ከጋብቻ ግንኙነቶች በፊት.", "አንድ ልጅ ከተወሰነ ሰይጣን ፈጽሞ አይጎዳውም."),
        "dua_ibrahim_children_protection" to DuaText("የቤት እና የልጆች ጥበቃ", "ጌታዬ ሆይ ይህችን ከተማ ጸጥታ አድርግልኝ እኔንም ልጆቼንም ጣኦት ከማምለክ አርቅ።", "የነቢዩ ኢብራሂም ዱአ (AS) - ለከተማው እና ለልጆቹ ደህንነት.", "በተውሂድ ላይ ለመቀጠል ዱዓ።"),
        "dua_drinking_milk" to DuaText("ወተት በሚጠጡበት ጊዜ", "አላህ ሆይ ባርክልን ለኛም አብዝተን ስጠን።", "ወተት በሚጠጡበት ጊዜ.", "ወተት እንደ ምግብ እና መጠጥ በቂ ነው."),
        "dua_iftar_host" to DuaText("ከሌሎች ጋር ፆምን ስትፈታ", "ጾመ ጾም ከአንተ ጋር ይሁን፣ ጻድቃን መብልህን ይብሉ፣ መላእክትም ይጸልዩልህ።", "በአንድ ሰው ቤት ፆም ሲፈታ።", "ለአስተናጋጁ የነብዩ ﷺ ዱአ።"),
    )
}
